import java.util.Scanner;

public class Main {
    static final int MAXP = 1000001 + 100000; // 1e6 + 1e5
    static final long MOD = 1000000007L; // 1e9 + 7
    static long k, p;
    static int tot;
    static long ans;
    static boolean[] vis = new boolean[MAXP];
    static int[] val = new int[MAXP];

    static void mod(long[] x) {
        x[0] = ((x[0] % MOD) + MOD) % MOD;
    }

    static void Bfs(int x) {
        tot++;
        int x0 = x;
        long w = 1;
        do {
            vis[x] = true;
            x = (int)((long)x * k % p);
            w = (w * k) % p;
        } while (x != x0);
        long[] ansArr = {ans};
        if (w == 1) {
            ansArr[0] = (ansArr[0] * p) % MOD;
        }
        ans = ansArr[0];
    }

    static void solve() {
        if (k == 0) {
            long w = 1;
            for (int i = 1; i <= p - 1; i++) {
                w = (w * p) % MOD;
            }
            System.out.println(w);
            return;
        }
        ans = 1;
        for (int i = 0; i <= p - 1; i++) {
            if (!vis[i]) {
                Bfs(i);
            }
        }
        System.out.println(ans);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        p = scanner.nextLong();
        k = scanner.nextLong();
        solve();
        scanner.close();
    }
}
